// Package views is the decode profile "views" of the Go conformance driver: the same bytes go through
// go-stellar-sdk's zero-copy XDR views (xdr.<Type>View, generated by xdrgen) and the view-based ingest
// extractors that production indexers run instead of the full decode:
//
//	xdr.LedgerCloseMetaBatchView → LedgerCloseMetas().All() → for each xdr.LedgerCloseMetaView:
//	    ingest.ExtractLedgerTxParts, ingest.EventsFromTxParts, ingest.FeesFromTxParts,
//	    ingest.LedgerTransactionViewRange, and the header helpers (LedgerSequence, LedgerHash, …)
//
// Every derived key is compared with what the same SDK version produces from the full decode
// (xdr.SafeUnmarshal, xdr.LedgerCloseMeta helpers and ingest.LedgerTransactionReader), so a difference between
// the two paths of one SDK is reported without any expected value: both sides come from the SDK under test, and
// the driver only says that they disagree.
//
// The views and extractors first shipped in go-stellar-sdk v0.8.0; only the version modules from v0.8.0 on
// import this package (driver.RegisterViews).
package views

import (
	"bytes"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"os"

	"github.com/stellar/go-stellar-sdk/ingest"
	"github.com/stellar/go-stellar-sdk/xdr"
)

// PlantEnv names the environment variable the harness self-test sets to plant a difference on the view path
// (value "tx-hash": the first transaction hash the view extractor reports is flipped), so that the comparison is
// shown to catch one. Nothing else reads it.
const PlantEnv = "XDRCHECK_GO_VIEWS_PLANT"

// maxMismatches bounds the differences listed for one input.
const maxMismatches = 20

// Decoder implements the driver's views hook.
type Decoder struct{}

// errTrailing is the consumed-length check: the view validated, but bytes follow the value.
type errTrailing struct{ extent, total int }

func (e errTrailing) Error() string {
	return fmt.Sprintf("the value ends at byte %d of %d (trailing bytes)", e.extent, e.total)
}

// validate is ValidateFull on the type's view followed by a consumed-length check against the view's own extent
// (Raw), which is what xdr.ValidateExact does in the SDK versions that have it (v0.9.0 and later); the two
// steps are spelled out so that v0.8.0, which has ValidateFull but not ValidateExact, runs the same check.
func validate[T interface {
	~[]byte
	ValidateFull() error
	Raw() ([]byte, error)
}](raw []byte) error {
	v := T(raw)
	if err := v.ValidateFull(); err != nil {
		return err
	}
	exact, err := v.Raw()
	if err != nil {
		return err
	}
	if len(exact) != len(raw) {
		return errTrailing{len(exact), len(raw)}
	}
	return nil
}

// validators are the view types of the XDR types the driver decodes by name.
var validators = map[string]func([]byte) error{
	"AccountId":                     validate[xdr.AccountIdView],
	"Asset":                         validate[xdr.AssetView],
	"BucketEntry":                   validate[xdr.BucketEntryView],
	"ChangeTrustAsset":              validate[xdr.ChangeTrustAssetView],
	"ClaimableBalanceId":            validate[xdr.ClaimableBalanceIdView],
	"ConfigSettingEntry":            validate[xdr.ConfigSettingEntryView],
	"ContractEvent":                 validate[xdr.ContractEventView],
	"ContractExecutable":            validate[xdr.ContractExecutableView],
	"DecoratedSignature":            validate[xdr.DecoratedSignatureView],
	"DiagnosticEvent":               validate[xdr.DiagnosticEventView],
	"FeeBumpTransactionEnvelope":    validate[xdr.FeeBumpTransactionEnvelopeView],
	"GeneralizedTransactionSet":     validate[xdr.GeneralizedTransactionSetView],
	"Hash":                          validate[xdr.HashView],
	"HostFunction":                  validate[xdr.HostFunctionView],
	"LedgerCloseMeta":               validate[xdr.LedgerCloseMetaView],
	"LedgerCloseMetaBatch":          validate[xdr.LedgerCloseMetaBatchView],
	"LedgerEntry":                   validate[xdr.LedgerEntryView],
	"LedgerEntryChange":             validate[xdr.LedgerEntryChangeView],
	"LedgerEntryChanges":            validate[xdr.LedgerEntryChangesView],
	"LedgerHeader":                  validate[xdr.LedgerHeaderView],
	"LedgerHeaderHistoryEntry":      validate[xdr.LedgerHeaderHistoryEntryView],
	"LedgerKey":                     validate[xdr.LedgerKeyView],
	"LedgerUpgrade":                 validate[xdr.LedgerUpgradeView],
	"Memo":                          validate[xdr.MemoView],
	"MuxedAccount":                  validate[xdr.MuxedAccountView],
	"Operation":                     validate[xdr.OperationView],
	"OperationResult":               validate[xdr.OperationResultView],
	"PoolId":                        validate[xdr.PoolIdView],
	"Preconditions":                 validate[xdr.PreconditionsView],
	"Price":                         validate[xdr.PriceView],
	"PublicKey":                     validate[xdr.PublicKeyView],
	"ScAddress":                     validate[xdr.ScAddressView],
	"ScError":                       validate[xdr.ScErrorView],
	"ScMap":                         validate[xdr.ScMapView],
	"ScpEnvelope":                   validate[xdr.ScpEnvelopeView],
	"ScpHistoryEntry":               validate[xdr.ScpHistoryEntryView],
	"ScVal":                         validate[xdr.ScValView],
	"ScVec":                         validate[xdr.ScVecView],
	"SignerKey":                     validate[xdr.SignerKeyView],
	"SorobanAuthorizationEntry":     validate[xdr.SorobanAuthorizationEntryView],
	"SorobanTransactionData":        validate[xdr.SorobanTransactionDataView],
	"StellarValue":                  validate[xdr.StellarValueView],
	"Transaction":                   validate[xdr.TransactionView],
	"TransactionEnvelope":           validate[xdr.TransactionEnvelopeView],
	"TransactionHistoryEntry":       validate[xdr.TransactionHistoryEntryView],
	"TransactionHistoryResultEntry": validate[xdr.TransactionHistoryResultEntryView],
	"TransactionMeta":               validate[xdr.TransactionMetaView],
	"TransactionResult":             validate[xdr.TransactionResultView],
	"TransactionResultMeta":         validate[xdr.TransactionResultMetaView],
	"TransactionResultPair":         validate[xdr.TransactionResultPairView],
	"TransactionSet":                validate[xdr.TransactionSetView],
	"TransactionSignaturePayload":   validate[xdr.TransactionSignaturePayloadView],
	"TransactionV1Envelope":         validate[xdr.TransactionV1EnvelopeView],
	"TrustLineAsset":                validate[xdr.TrustLineAssetView],
	"UpgradeEntryMeta":              validate[xdr.UpgradeEntryMetaView],
}

// Validate checks that raw holds exactly one well-formed value of the named type (its Go name, as the driver's
// registry spells it) through the type's view (validate). known is false when there is no view type.
func (Decoder) Validate(goName string, raw []byte) (known bool, err error) {
	v, found := validators[goName]
	if !found {
		return false, nil
	}
	return true, v(raw)
}

// ErrorCode maps a view error to the driver's reason-code vocabulary.
func (Decoder) ErrorCode(err error, inputLen int) string {
	var te errTrailing
	if errors.As(err, &te) {
		return "trailing_bytes"
	}
	var ve *xdr.ViewError
	if !errors.As(err, &ve) {
		return "decode_error"
	}
	switch ve.Kind {
	case xdr.ViewErrUnknownDiscriminant:
		return "union_arm_undeclared"
	case xdr.ViewErrBadBoolValue:
		return "bool_range"
	case xdr.ViewErrNonZeroPadding:
		return "nonzero_padding"
	case xdr.ViewErrMaxDepth:
		return "depth"
	case xdr.ViewErrOpaqueExceedsMax, xdr.ViewErrArrayCountExceedsMax:
		return "length_exceeds_max"
	case xdr.ViewErrShortBuffer, xdr.ViewErrArrayCountExceedsData:
		return "length_exceeds_input"
	}
	return "decode_error"
}

// Report is what the view path did with a ledger input and how it compares with the full decode.
type Report struct {
	// EntryPoint and Err: the first view entry point that refused the input; nil Err means the view path
	// accepted it.
	EntryPoint string
	Err        error
	// What the view path read: ledgers, transactions (TxProcessing elements) and their hashes in apply order.
	Ledgers      int
	Transactions int
	TxHashes     []string
	// Mismatches lists where the view path and the full decode disagree, each naming the entry point.
	Mismatches []string
}

func (r *Report) mismatch(format string, a ...any) {
	if len(r.Mismatches) < maxMismatches {
		r.Mismatches = append(r.Mismatches, fmt.Sprintf(format, a...))
	}
}

func (r *Report) refuse(entry string, err error) Report {
	r.EntryPoint, r.Err = entry, err
	return *r
}

// Ledgers runs the view path over a LedgerCloseMeta or LedgerCloseMetaBatch (goName) and compares it with the
// full decode: fullBatch is the batch the strict decode produced (nil for a single ledger), full its ledgers
// (nil when the strict decode refused the bytes, in which case only the view path runs). The passphrase pairs
// envelopes to transactions; without one the read-path comparison is skipped.
func (Decoder) Ledgers(goName string, raw []byte, passphrase string, full []xdr.LedgerCloseMeta, fullBatch *xdr.LedgerCloseMetaBatch) Report {
	var r Report
	var lcms []xdr.LedgerCloseMetaView
	switch goName {
	case "LedgerCloseMeta":
		lcms = []xdr.LedgerCloseMetaView{xdr.LedgerCloseMetaView(raw)}
	case "LedgerCloseMetaBatch":
		b := xdr.LedgerCloseMetaBatchView(raw)
		metas, err := b.LedgerCloseMetas()
		if err != nil {
			return r.refuse("xdr.LedgerCloseMetaBatchView.LedgerCloseMetas", err)
		}
		all, err := metas.All()
		if err != nil {
			return r.refuse("xdr.LedgerCloseMetaBatchLedgerCloseMetasView.All", err)
		}
		lcms = all
		start, serr := xdr.Try(func() uint32 { return uint32(b.MustStartSequence().MustValue()) })
		end, eerr := xdr.Try(func() uint32 { return uint32(b.MustEndSequence().MustValue()) })
		if serr != nil || eerr != nil {
			return r.refuse("xdr.LedgerCloseMetaBatchView.StartSequence/EndSequence", errors.Join(serr, eerr))
		}
		if fullBatch != nil {
			if start != uint32(fullBatch.StartSequence) || end != uint32(fullBatch.EndSequence) {
				r.mismatch("batch start/end: view %d..%d, full %d..%d", start, end, fullBatch.StartSequence, fullBatch.EndSequence)
			}
			if len(all) != len(fullBatch.LedgerCloseMetas) {
				r.mismatch("batch ledgers: view %d, full %d", len(all), len(fullBatch.LedgerCloseMetas))
			}
		}
	default:
		return r.refuse("views", fmt.Errorf("%s is not a ledger type", goName))
	}
	r.Ledgers = len(lcms)
	for i, v := range lcms {
		var f *xdr.LedgerCloseMeta
		if full != nil && i < len(full) {
			f = &full[i]
		}
		if rr := ledger(&r, i, v, f, passphrase); rr != nil {
			return *rr
		}
	}
	return r
}

// ledger runs the view path over one ledger and compares it with the full decode f (nil: none). It returns a
// refusal report when a view entry point refused the ledger.
func ledger(r *Report, li int, v xdr.LedgerCloseMetaView, f *xdr.LedgerCloseMeta, passphrase string) *Report {
	at := func(entry string) string { return fmt.Sprintf("ledger %d: %s", li, entry) }
	refuse := func(entry string, err error) *Report {
		rr := r.refuse(at(entry), err)
		return &rr
	}
	seq, err := v.LedgerSequence()
	if err != nil {
		return refuse("xdr.LedgerCloseMetaView.LedgerSequence", err)
	}
	hash, err := v.LedgerHash()
	if err != nil {
		return refuse("xdr.LedgerCloseMetaView.LedgerHash", err)
	}
	prev, err := v.PreviousLedgerHash()
	if err != nil {
		return refuse("xdr.LedgerCloseMetaView.PreviousLedgerHash", err)
	}
	closeTime, err := v.LedgerCloseTime()
	if err != nil {
		return refuse("xdr.LedgerCloseMetaView.LedgerCloseTime", err)
	}
	if f != nil {
		if seq != f.LedgerSequence() {
			r.mismatch("%s: view %d, full %d", at("LedgerSequence"), seq, f.LedgerSequence())
		}
		if fh := f.LedgerHash(); !bytes.Equal(hash, fh[:]) {
			r.mismatch("%s: view %x, full %x", at("LedgerHash"), hash, fh[:])
		}
		if fp := f.PreviousLedgerHash(); !bytes.Equal(prev, fp[:]) {
			r.mismatch("%s: view %x, full %x", at("PreviousLedgerHash"), prev, fp[:])
		}
		if closeTime != f.LedgerCloseTime() {
			r.mismatch("%s: view %d, full %d", at("LedgerCloseTime"), closeTime, f.LedgerCloseTime())
		}
		closeTimeMs(r, at, v, *f)
	}

	parts, err := ingest.ExtractLedgerTxParts(v)
	if err != nil {
		return refuse("ingest.ExtractLedgerTxParts", err)
	}
	if os.Getenv(PlantEnv) == "tx-hash" && len(parts) > 0 {
		parts[0].Hash[0] ^= 0xff
	}
	r.Transactions += len(parts)
	for _, p := range parts {
		r.TxHashes = append(r.TxHashes, hex.EncodeToString(p.Hash[:]))
	}
	events, err := ingest.EventsFromTxParts(parts)
	if err != nil {
		return refuse("ingest.EventsFromTxParts", err)
	}
	fees, feeErr := ingest.FeesFromTxParts(parts)

	var txs []ingest.LedgerTransactionView
	var rangeErr error
	if passphrase != "" {
		txs, rangeErr = ingest.LedgerTransactionViewRange(v, 0, 0, passphrase)
	}
	if f == nil {
		switch {
		case feeErr != nil:
			return refuse("ingest.FeesFromTxParts", feeErr)
		case rangeErr != nil:
			return refuse("ingest.LedgerTransactionViewRange", rangeErr)
		}
		return nil
	}

	n := f.CountTransactions()
	if len(parts) != n {
		r.mismatch("%s: view %d transactions, full %d", at("ingest.ExtractLedgerTxParts"), len(parts), n)
		return nil
	}
	for i, p := range parts {
		pair := f.TransactionResultPair(i)
		if p.Hash != [32]byte(pair.TransactionHash) {
			r.mismatch("%s tx %d: hash view %x, full %x", at("ingest.ExtractLedgerTxParts"), i, p.Hash[:], pair.TransactionHash[:])
		}
		fb, inner := false, [32]byte{}
		if ip, isFB := pair.Result.Result.GetInnerResultPair(); isFB {
			fb, inner = true, [32]byte(ip.TransactionHash)
		}
		if p.FeeBump != fb || (fb && p.InnerHash != inner) {
			r.mismatch("%s tx %d: fee bump view %v %x, full %v %x", at("ingest.ExtractLedgerTxParts"), i, p.FeeBump, p.InnerHash[:], fb, inner[:])
		}
		compareTxEvents(r, at("ingest.EventsFromTxParts"), i, events[i], f.TxApplyProcessing(i))
	}
	compareFees(r, at("ingest.FeesFromTxParts"), fees, feeErr, *f)
	if passphrase != "" {
		compareRange(r, at("ingest.LedgerTransactionViewRange"), txs, rangeErr, *f, passphrase, seq, closeTime)
	}
	return nil
}

// closeTimeMs compares the millisecond close time where the SDK has it on both paths (v0.9.0 and later).
func closeTimeMs(r *Report, at func(string) string, v xdr.LedgerCloseMetaView, f xdr.LedgerCloseMeta) {
	type ms interface{ LedgerCloseTimeMs() (int64, error) }
	vm, ok1 := any(v).(ms)
	fm, ok2 := any(f).(ms)
	if !ok1 || !ok2 {
		return
	}
	a, aerr := vm.LedgerCloseTimeMs()
	b, berr := fm.LedgerCloseTimeMs()
	switch {
	case (aerr == nil) != (berr == nil):
		r.mismatch("%s: view error %v, full error %v", at("LedgerCloseTimeMs"), aerr, berr)
	case aerr == nil && a != b:
		r.mismatch("%s: view %d, full %d", at("LedgerCloseTimeMs"), a, b)
	}
}

func marshal(v interface{ MarshalBinary() ([]byte, error) }) []byte {
	b, err := v.MarshalBinary()
	if err != nil {
		return nil
	}
	return b
}

// compareTxEvents compares EventsFromTxParts with the events of the full meta, in the shape EventsFromTxParts
// documents: V4 top-level transaction events and one group per operation; V3 one group when SorobanMeta is
// present and none when it is absent; nothing for V0–V2.
func compareTxEvents(r *Report, entry string, i int, got ingest.TxEvents, meta xdr.TransactionMeta) {
	var wantTx [][]byte
	var wantOps [][][]byte
	switch meta.V {
	case 3:
		if sm := meta.MustV3().SorobanMeta; sm != nil {
			g := [][]byte{}
			for _, e := range sm.Events {
				g = append(g, marshal(e))
			}
			wantOps = append(wantOps, g)
		}
	case 4:
		m := meta.MustV4()
		for _, e := range m.Events {
			wantTx = append(wantTx, marshal(e))
		}
		for _, op := range m.Operations {
			g := [][]byte{}
			for _, e := range op.Events {
				g = append(g, marshal(e))
			}
			wantOps = append(wantOps, g)
		}
	}
	if d := diffRaws(got.TransactionEvents, wantTx); d != "" {
		r.mismatch("%s tx %d: transaction events %s", entry, i, d)
	}
	if len(got.OperationEvents) != len(wantOps) {
		r.mismatch("%s tx %d: view %d operation groups, full %d", entry, i, len(got.OperationEvents), len(wantOps))
		return
	}
	for k := range wantOps {
		if d := diffRaws(got.OperationEvents[k], wantOps[k]); d != "" {
			r.mismatch("%s tx %d op %d: contract events %s", entry, i, k, d)
		}
	}
}

// diffRaws describes the first difference between two lists of encoded values, or "".
func diffRaws(view, full [][]byte) string {
	if len(view) != len(full) {
		return fmt.Sprintf("view %d, full %d", len(view), len(full))
	}
	for k := range view {
		if !bytes.Equal(view[k], full[k]) {
			return fmt.Sprintf("element %d differs (view %d bytes, full %d bytes)", k, len(view[k]), len(full[k]))
		}
	}
	return ""
}

// compareFees recomputes FeesFromTxParts' documented classification from the full decode and compares.
func compareFees(r *Report, entry string, got ingest.LedgerFees, gotErr error, f xdr.LedgerCloseMeta) {
	var classic, soroban []uint64
	var wantErr error
	for i := 0; i < f.CountTransactions() && wantErr == nil; i++ {
		fee, bucket, err := classify(f.TransactionResultPair(i), f.TxApplyProcessing(i))
		switch {
		case err != nil:
			wantErr = fmt.Errorf("tx %d: %w", i, err)
		case bucket == "classic":
			classic = append(classic, fee)
		case bucket == "soroban":
			soroban = append(soroban, fee)
		}
	}
	switch {
	case (gotErr == nil) != (wantErr == nil):
		r.mismatch("%s: view error %v, full classification error %v", entry, gotErr, wantErr)
	case gotErr != nil:
	case !equalU64(got.ClassicFeesPerOp, classic):
		r.mismatch("%s: classic fees per op view %v, full %v", entry, got.ClassicFeesPerOp, classic)
	case !equalU64(got.SorobanInclusionFees, soroban):
		r.mismatch("%s: soroban inclusion fees view %v, full %v", entry, got.SorobanInclusionFees, soroban)
	}
}

func equalU64(a, b []uint64) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// classify is FeesFromTxParts' per-transaction rule (ingest.LedgerFees) on the full decode.
func classify(pair xdr.TransactionResultPair, meta xdr.TransactionMeta) (uint64, string, error) {
	charged := int64(pair.Result.FeeCharged)
	if charged < 0 {
		return 0, "", errors.New("fee charged cannot be negative")
	}
	var ext *xdr.SorobanTransactionMetaExt
	present := false
	switch meta.V {
	case 3:
		if sm := meta.MustV3().SorobanMeta; sm != nil {
			present, ext = true, &sm.Ext
		}
	case 4:
		if sm := meta.MustV4().SorobanMeta; sm != nil {
			present, ext = true, &sm.Ext
		}
	}
	if present {
		if ext.V != 1 || ext.V1 == nil {
			return 0, "", nil
		}
		nonRef, ref := int64(ext.V1.TotalNonRefundableResourceFeeCharged), int64(ext.V1.TotalRefundableResourceFeeCharged)
		if nonRef < 0 || ref < 0 {
			return 0, "", errors.New("resource fee charged cannot be negative")
		}
		res := nonRef + ref
		if res < 0 {
			return 0, "", errors.New("resource fee charged overflows int64")
		}
		if res > charged {
			return 0, "", fmt.Errorf("resource fee charged %d exceeds fee charged %d", res, charged)
		}
		return uint64(charged - res), "soroban", nil
	}
	ops := 0
	res := pair.Result.Result
	switch res.Code {
	case xdr.TransactionResultCodeTxSuccess, xdr.TransactionResultCodeTxFailed:
		if res.Results != nil {
			ops = len(*res.Results)
		}
	case xdr.TransactionResultCodeTxFeeBumpInnerSuccess, xdr.TransactionResultCodeTxFeeBumpInnerFailed:
		if ip := res.InnerResultPair; ip != nil {
			ir := ip.Result.Result
			if (ir.Code == xdr.TransactionResultCodeTxSuccess || ir.Code == xdr.TransactionResultCodeTxFailed) && ir.Results != nil {
				ops = len(*ir.Results)
			}
		}
	}
	if ops == 0 {
		return 0, "", nil
	}
	return uint64(charged) / uint64(ops), "classic", nil
}

// compareRange compares the read path (LedgerTransactionViewRange) with the parsed reader
// (ingest.LedgerTransactionReader) of the same SDK: transaction by transaction, in apply order.
func compareRange(r *Report, entry string, txs []ingest.LedgerTransactionView, viewErr error, f xdr.LedgerCloseMeta, passphrase string, seq uint32, closeTime int64) {
	var full []ingest.LedgerTransaction
	var fullErr error
	rd, err := ingest.NewLedgerTransactionReaderFromLedgerCloseMeta(passphrase, f)
	if err != nil {
		fullErr = err
	} else {
		for {
			tx, err := rd.Read()
			if err == io.EOF {
				break
			}
			if err != nil {
				fullErr = err
				break
			}
			full = append(full, tx)
		}
	}
	if (viewErr == nil) != (fullErr == nil) {
		r.mismatch("%s: view error %v, ingest.LedgerTransactionReader error %v", entry, viewErr, fullErr)
		return
	}
	if viewErr != nil {
		return
	}
	if len(txs) != len(full) {
		r.mismatch("%s: view %d transactions, reader %d", entry, len(txs), len(full))
		return
	}
	for i := range txs {
		v, t := txs[i], full[i]
		tag := fmt.Sprintf("%s tx %d", entry, i)
		if v.Hash != [32]byte(t.Result.TransactionHash) {
			r.mismatch("%s: hash view %x, reader %x", tag, v.Hash[:], t.Result.TransactionHash[:])
		}
		if uint32(v.ApplicationOrder) != t.Index {
			r.mismatch("%s: application order view %d, reader %d", tag, v.ApplicationOrder, t.Index)
		}
		if v.FeeBump != t.Envelope.IsFeeBump() {
			r.mismatch("%s: fee bump view %v, reader %v", tag, v.FeeBump, t.Envelope.IsFeeBump())
		}
		if v.Successful != t.Result.Successful() {
			r.mismatch("%s: successful view %v, reader %v", tag, v.Successful, t.Result.Successful())
		}
		if !bytes.Equal(v.Envelope, marshal(t.Envelope)) {
			r.mismatch("%s: envelope bytes differ", tag)
		}
		if !bytes.Equal(v.Result, marshal(t.Result.Result)) {
			r.mismatch("%s: result bytes differ", tag)
		}
		if !bytes.Equal(v.Meta, marshal(t.UnsafeMeta)) {
			r.mismatch("%s: meta bytes differ", tag)
		}
		if v.LedgerSequence != seq || v.LedgerCloseTime != closeTime {
			r.mismatch("%s: ledger %d at %d, header %d at %d", tag, v.LedgerSequence, v.LedgerCloseTime, seq, closeTime)
		}
		ev, err := t.GetTransactionEvents()
		if err != nil {
			r.mismatch("%s: view read the events, reader GetTransactionEvents refused: %v", tag, err)
			continue
		}
		var diag, txe [][]byte
		for _, e := range ev.DiagnosticEvents {
			diag = append(diag, marshal(e))
		}
		for _, e := range ev.TransactionEvents {
			txe = append(txe, marshal(e))
		}
		if d := diffRaws(v.DiagnosticEvents, diag); d != "" {
			r.mismatch("%s: diagnostic events %s", tag, d)
		}
		if d := diffRaws(v.TransactionEvents, txe); d != "" {
			r.mismatch("%s: transaction events %s", tag, d)
		}
		if len(v.ContractEvents) != len(ev.OperationEvents) {
			r.mismatch("%s: view %d operation event groups, reader %d", tag, len(v.ContractEvents), len(ev.OperationEvents))
			continue
		}
		for k, g := range ev.OperationEvents {
			var want [][]byte
			for _, e := range g {
				want = append(want, marshal(e))
			}
			if d := diffRaws(v.ContractEvents[k], want); d != "" {
				r.mismatch("%s op %d: contract events %s", tag, k, d)
			}
		}
	}
}
